 double scale=std::min(1.0,double(maxSide)/double(std::max(w,h)));UINT nw=std::max<UINT>(16,UINT(w*scale)),nh=std::max<UINT>(16,UINT(h*scale));Com<IWICBitmapScaler> scaler;check(wic->CreateBitmapScaler(&scaler),"scaler");check(scaler->Initialize(frame.Get(),nw,nh,WICBitmapInterpolationModeFant),"scale");
